open('/kaggle/working/verify/run_aya.py', 'w', encoding='utf-8').write('"""Run Aya Expanse 8B on both verification sets (greedy, fp16, 2xT4)."""\nimport json, time\nfrom vllm import LLM, SamplingParams\n\nllm = LLM(model="CohereLabs/aya-expanse-8b", dtype="half", tensor_parallel_size=2, max_model_len=4096,\n          gpu_memory_utilization=0.88, seed=0)\n\ndef run(inp, out, max_tokens):\n    rows = [json.loads(l) for l in open(inp, encoding="utf-8")]\n    t = time.time()\n    res = llm.chat([r["messages"] for r in rows], SamplingParams(temperature=0.0, max_tokens=max_tokens), use_tqdm=True)\n    with open(out, "w", encoding="utf-8") as f:\n        for r, o in zip(rows, res):\n            r = {k: v for k, v in r.items() if k != "messages"}\n            r["aya_raw"] = o.outputs[0].text.strip()\n            f.write(json.dumps(r, ensure_ascii=False) + "\\n")\n    print(f"{out}: {len(rows)} rows in {time.time() - t:.0f}s")\n\nrun("/kaggle/working/verify/judge_sample.jsonl", "/kaggle/working/verify/aya_judge.jsonl", 16)\nrun("/kaggle/working/verify/item_audit.jsonl", "/kaggle/working/verify/aya_audit.jsonl", 300)\n')

hits = glob.glob("/kaggle/input/**/clm/src/clm/prompts.py", recursive=True)
if not hits:
    raise RuntimeError("STOP: add the output of clm-main-r1-4-judge as input (Add Input -> Your Work)")
CLM = hits[0].rsplit("/src/clm/prompts.py", 1)[0]
print("clm root:", CLM)
sys.path[:0] = [CLM + "/src", "/kaggle/working/verify"]
import pandas as pd
from clm import prompts
import verify_build as vb
items = {j["item_id"]: j for j in map(json.loads, open(CLM + "/data/items/items_main.jsonl", encoding="utf-8"))}
scored = pd.read_csv(CLM + "/results/main_r1/scored.csv")
keys = json.load(open("/kaggle/working/verify/judge_keys.json"))
J = vb.dumps(vb.judge_rows(keys, scored, items, prompts))
A = vb.dumps(vb.audit_rows(items))
for name, text, want in (("judge_sample", J, "f0f2a279a13468abe93f2ff961d88310e2ccd2725cbb27fc701161245f645932"), ("item_audit", A, "598e199bf0c3351b0f6963d71359507416b197b0e3aca24ecf29462afbf41764")):
    got = hashlib.sha256(text.encode("utf-8")).hexdigest()
    print(name, text.count("\n"), "rows, sha256 match:", got == want)
    if got != want:
        raise RuntimeError(f"STOP: {name} differs from the locally built file")
    open(f"/kaggle/working/verify/{name}.jsonl", "w", encoding="utf-8").write(text)

r = subprocess.run(["python", "/kaggle/working/verify/run_aya.py"], capture_output=True, text=True)
print(r.stdout[-3000:])
if r.returncode != 0:
    print(r.stderr[-5000:]); raise RuntimeError("STOP: Aya run failed (see above)")

for f in ("aya_judge", "aya_audit"):
    rows = [json.loads(l) for l in open(f"/kaggle/working/verify/{f}.jsonl", encoding="utf-8")]
    print(f, len(rows))
    for x in rows[:3]:
        print("  ", x["aya_raw"][:160].replace("\n", " "))
shutil.make_archive("/kaggle/working/verify_aya_results", "zip", "/kaggle/working/verify")
print("Download zip: /kaggle/working/verify_aya_results.zip (Output tab)")
